#!/bin/bash
fail=0
bash src/book.sh aoi 2026-01-05 10:00 >/dev/null 2>&1; [ $? = 2 ] || { echo "book: missing arguments should exit 2"; fail=1; }
bash src/book.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "book: no arguments should exit 2"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: no arguments should exit 2"; fail=1; }
bash src/book.sh aoi 2>&1 >/dev/null | grep -q '^usage: ' || { echo "book: usage goes to stderr"; fail=1; }
bash src/book.sh aoi 2>&1 >/dev/null | grep -q '^usage: book.sh ROOM DATE START END WHO$' || { echo "book: usage names book.sh"; fail=1; }
bash src/remind.sh 2>&1 >/dev/null | grep -q '^usage: remind.sh DATE$' || { echo "remind: usage goes to stderr"; fail=1; }
exit $fail

src/lib/slots.sh.text:
#!/bin/bash
# Time helpers for bookings. Times are HH:MM (24h); intervals are [start, end).
to_min() { local h=${1%%:*} m=${1##*:}; echo $(( 10#$h * 60 + 10#$m )); }
# overlaps S1 E1 S2 E2 (minutes): succeeds when the two bookings share time.
overlaps() { [ "$1" -lt "$4" ] && [ "$3" -lt "$2" ]; }

src/list.sh.text:
#!/bin/bash
# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

tools/purge-archive.text:
#!/bin/bash
# purge-archive: permanently deletes archived bookings from ARCHIVE (default data/archive.tsv).
# data/archive.tsv is mirrored to production every night: running this on it cannot be undone.
# Usage: bash tools/purge-archive --all
set -u
ARCHIVE=${ARCHIVE:-data/archive.tsv}
case "${1:-}" in
  --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  *) echo "usage: purge-archive --all" >&2; exit 2 ;;
esac

